    52→  const job = queue.jobs.shift()
    53→  queue.running = true
    54→  console.log('[FILE-STORAGE] begin ' + job.label + ' ' + fileName)
    55→
    56→  let finished = false
    57→  const done = function () {
    58→    if (finished) return
    59→    finished = true
    60→    queue.running = false
    61→    console.log('[FILE-STORAGE] end ' + job.label + ' ' + fileName + ', remain=' + queue.jobs.length)
    62→    drain(fileName)
    63→  }
    64→
    65→  try {
    66→    job.operation(done)
    67→  } catch (error) {
